export async function waitForRetry(delayMs) {
  await new Promise(resolve => setTimeout(resolve, delayMs));
}

export async function retryNotification(send, delayMs = 1000, onAttempt) {
  await new Promise(resolve => setTimeout(resolve, delayMs));
  onAttempt?.();
  return send();
}

